<?php
/**
 * The submission store: the `agentshell_entry` post type and its meta.
 *
 * ## A submission is immutable
 *
 * The record is written once, inside one bounded transaction, and after that
 * the submitted values and the form version they were validated against are
 * never edited. The only writes that touch a submission afterwards are the
 * **notification record** — which is lifecycle state, not submission content —
 * and the post status (trash/restore) or a deliberate erasure.
 *
 * The post title is generated by the server. No submitted value lands in it,
 * so no personal data sits in a field an admin list table sorts on or a search
 * index carries.
 *
 * ## Why the meta rows are written directly
 *
 * `add_post_meta()` runs the value through `wp_unslash()`, which is correct for
 * data that came from a request and wrong for a JSON document this plugin
 * produced: a literal backslash in a visitor's message would be eaten on the
 * way in. The store therefore writes the exact bytes it hashed, with
 * `$wpdb->insert()`, and invalidates the post-meta cache itself. It also means
 * the value a compare-and-swap reads back is the value that was written.
 *
 * ## Data minimisation is a property of the write
 *
 * The handler passes exactly the declared fields; this store stores exactly
 * what it is given. A value for an undeclared key never reaches here, which is
 * what makes cross-form leakage impossible rather than merely unlikely.
 *
 * @package AgentShell_Forms
 */

namespace AgentShell_Forms;

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

/**
 * Create, read, export and delete submissions.
 */
class Submission_Store {

	/**
	 * The form's internal identifier.
	 */
	const META_FORM_ID = '_agentshell_form_id';

	/**
	 * The published version the submission was validated against.
	 */
	const META_FORM_VERSION = '_agentshell_form_version';

	/**
	 * The submitted values, JSON, keyed by field key.
	 */
	const META_DATA = '_agentshell_form_data';

	/**
	 * Received-at, source, the hashed address, and the user agent when enabled.
	 */
	const META_META = '_agentshell_form_meta';

	/**
	 * `clean`, `spam` or `unverified`.
	 */
	const META_SPAM = '_agentshell_form_spam';

	/**
	 * The administrator-notification record.
	 */
	const META_NOTIFICATION = '_agentshell_form_notification';

	/**
	 * The submitter-confirmation record.
	 */
	const META_NOTIFICATION_CONFIRMATION = '_agentshell_form_notification_confirmation';

	/**
	 * The SHA-256 of the canonical submitted payload.
	 */
	const META_HASH = '_agentshell_form_hash';

	/**
	 * The challenge token hash this submission consumed.
	 */
	const META_CHALLENGE = '_agentshell_form_challenge';

	/**
	 * The option holding the site-wide retention default, in days.
	 */
	const OPTION_RETENTION_DAYS = 'agentshell_forms_retention_days';

	/**
	 * The default retention period when the site has not set one (§6.4).
	 */
	const DEFAULT_RETENTION_DAYS = 90;

	/**
	 * The largest stored payload, in bytes. A submission larger than this is
	 * refused by the handler before it reaches here; the bound exists here too
	 * so a caller that bypasses the handler cannot write an unbounded row.
	 */
	const MAX_STORED_BYTES = 131072;

	/**
	 * Every meta key a submission owns.
	 *
	 * @return array<int,string>
	 */
	public static function meta_keys() {
		return array(
			self::META_FORM_ID,
			self::META_FORM_VERSION,
			self::META_DATA,
			self::META_META,
			self::META_SPAM,
			self::META_NOTIFICATION,
			self::META_NOTIFICATION_CONFIRMATION,
			self::META_HASH,
			self::META_CHALLENGE,
		);
	}

	/**
	 * The notification record key for a kind.
	 *
	 * @param string $kind `admin` or `confirmation`.
	 * @return string
	 */
	public static function notification_key( $kind ) {
		return 'confirmation' === (string) $kind ? self::META_NOTIFICATION_CONFIRMATION : self::META_NOTIFICATION;
	}

	/**
	 * The site-wide retention default, in days.
	 *
	 * @return int
	 */
	public static function site_retention_days() {
		$days = (int) get_option( self::OPTION_RETENTION_DAYS, self::DEFAULT_RETENTION_DAYS );

		return $days > 0 ? $days : self::DEFAULT_RETENTION_DAYS;
	}

	/**
	 * The canonical hash of a submission payload.
	 *
	 * Sorted keys, so key order in the request cannot change the hash; the form
	 * and version are included so the same values against a different schema
	 * are a different record.
	 *
	 * @param string $form_id The form's internal identifier.
	 * @param int    $version The published version.
	 * @param array  $fields  The validated values.
	 * @return string 64 hexadecimal characters.
	 */
	public static function hash_payload( $form_id, $version, array $fields ) {
		ksort( $fields );

		return hash(
			'sha256',
			(string) wp_json_encode(
				array(
					'form_id' => (string) $form_id,
					'version' => (int) $version,
					'fields'  => $fields,
				)
			)
		);
	}

	/**
	 * Create one submission.
	 *
	 * Everything is written in one SQL transaction: the post row, every meta
	 * row and the hash. A failure leaves no post, no meta and no cached copy,
	 * which is what lets the caller honestly report that nothing was stored.
	 *
	 * @param array $args {
	 *     @type string $form_id      The form's internal identifier.
	 *     @type string $form_name    The form's name, for the generated title.
	 *     @type int    $form_version The published version validated against.
	 *     @type array  $fields       Validated values, keyed by field key.
	 *     @type string $spam_status  `clean`, `spam` or `unverified`.
	 *     @type array  $meta         Received-at and source facts.
	 *     @type string $challenge    The challenge token hash, or ''.
	 *     @type array|null $notification The administrator record, or null.
	 *     @type array|null $confirmation The confirmation record, or null.
	 * }
	 * @return array{post_id:int,hash:string}|\WP_Error
	 */
	public static function create( array $args ) {
		global $wpdb;

		$form_id      = isset( $args['form_id'] ) ? (string) $args['form_id'] : '';
		$form_version = isset( $args['form_version'] ) ? (int) $args['form_version'] : 0;
		$fields       = isset( $args['fields'] ) && is_array( $args['fields'] ) ? $args['fields'] : array();
		$spam         = isset( $args['spam_status'] ) ? (string) $args['spam_status'] : 'clean';
		$meta         = isset( $args['meta'] ) && is_array( $args['meta'] ) ? $args['meta'] : array();
		$challenge    = isset( $args['challenge'] ) ? (string) $args['challenge'] : '';
		$form_name    = isset( $args['form_name'] ) ? (string) $args['form_name'] : '';
		$notification = isset( $args['notification'] ) && is_array( $args['notification'] ) ? $args['notification'] : null;
		$confirmation = isset( $args['confirmation'] ) && is_array( $args['confirmation'] ) ? $args['confirmation'] : null;

		if ( ! in_array( $spam, array( 'clean', 'spam', 'unverified' ), true ) ) {
			$spam = 'clean';
		}

		$data_json = (string) wp_json_encode( $fields );

		if ( strlen( $data_json ) > self::MAX_STORED_BYTES ) {
			return new \WP_Error(
				'form_submission_too_large',
				__( 'The submission is larger than this form can store.', 'agentshell-forms' )
			);
		}

		$hash = self::hash_payload( $form_id, $form_version, $fields );

		$title = sprintf(
			/* translators: 1: form name, 2: date, 3: time */
			__( '%1$s — %2$s %3$s', 'agentshell-forms' ),
			'' !== $form_name ? $form_name : __( 'Form submission', 'agentshell-forms' ),
			gmdate( 'Y-m-d' ),
			gmdate( 'H:i' )
		);

		$rows = array(
			self::META_FORM_ID      => $form_id,
			self::META_FORM_VERSION => (string) $form_version,
			self::META_DATA         => $data_json,
			self::META_META         => (string) wp_json_encode( $meta ),
			self::META_SPAM         => $spam,
			self::META_HASH         => $hash,
			self::META_CHALLENGE    => $challenge,
		);

		if ( null !== $notification ) {
			$rows[ self::META_NOTIFICATION ] = (string) wp_json_encode( $notification );
		}

		if ( null !== $confirmation ) {
			$rows[ self::META_NOTIFICATION_CONFIRMATION ] = (string) wp_json_encode( $confirmation );
		}

		$tables = array( $wpdb->posts, $wpdb->postmeta );

		$result = Form_DB::run(
			$tables,
			function () use ( $wpdb, $title, $rows, $form_id, $form_version ) {
				$post_id = wp_insert_post(
					array(
						'post_type'    => Form_Post_Types::ENTRY,
						'post_status'  => 'publish',
						'post_title'   => $title,
						'post_content' => '',
						'post_author'  => 0,
						'post_name'    => '',
						'meta_input'   => array(),
					),
					true
				);

				if ( is_wp_error( $post_id ) ) {
					return $post_id;
				}

				$post_id = (int) $post_id;

				if ( $post_id < 1 ) {
					return new \WP_Error(
						'form_submission_write_failed',
						__( 'The submission could not be stored.', 'agentshell-forms' )
					);
				}

				foreach ( $rows as $key => $value ) {
					$inserted = $wpdb->insert(
						$wpdb->postmeta,
						array(
							'post_id'    => $post_id,
							'meta_key'   => (string) $key, // phpcs:ignore WordPress.DB.SlowDBQuery.slow_db_query_meta_key
							'meta_value' => (string) $value, // phpcs:ignore WordPress.DB.SlowDBQuery.slow_db_query_meta_value
						),
						array( '%d', '%s', '%s' )
					);

					if ( false === $inserted ) {
						return new \WP_Error(
							'form_submission_write_failed',
							__( 'The submission metadata could not be stored.', 'agentshell-forms' ),
							array( 'form_id' => $form_id, 'version' => $form_version )
						);
					}
				}

				if ( function_exists( 'wp_cache_delete' ) ) {
					wp_cache_delete( $post_id, 'post_meta' );
				}

				return array( 'post_id' => $post_id, 'hash' => '' );
			}
		);

		if ( is_wp_error( $result ) ) {
			return $result;
		}

		if ( ! is_array( $result ) || ! isset( $result['post_id'] ) ) {
			return new \WP_Error(
				'form_submission_write_failed',
				__( 'The submission could not be stored.', 'agentshell-forms' )
			);
		}

		$result['hash'] = $hash;

		return $result;
	}

	/**
	 * Read one submission.
	 *
	 * @param int  $post_id The entry post id.
	 * @param bool $values  Whether to include the submitted values.
	 * @return array|\WP_Error
	 */
	public static function get( $post_id, $values = true ) {
		$post = get_post( (int) $post_id );

		if ( ! $post instanceof \WP_Post || Form_Post_Types::ENTRY !== $post->post_type ) {
			return new \WP_Error( 'form_submission_not_found', __( 'No submission has that id.', 'agentshell-forms' ) );
		}

		$record = array(
			'id'              => (int) $post->ID,
			'status'          => (string) $post->post_status,
			'title'           => (string) $post->post_title,
			'form_id'         => self::meta( $post->ID, self::META_FORM_ID ),
			'form_version'    => (int) self::meta( $post->ID, self::META_FORM_VERSION ),
			'spam_status'     => self::meta( $post->ID, self::META_SPAM ),
			'hash'            => self::meta( $post->ID, self::META_HASH ),
			'challenge'       => self::meta( $post->ID, self::META_CHALLENGE ),
			'received_at'     => (string) $post->post_date_gmt,
			'notification'    => self::decode( self::meta( $post->ID, self::META_NOTIFICATION ) ),
			'confirmation'    => self::decode( self::meta( $post->ID, self::META_NOTIFICATION_CONFIRMATION ) ),
			'meta'            => self::decode( self::meta( $post->ID, self::META_META ) ),
			'field_count'     => 0,
			'values'          => array(),
		);

		$data = self::decode( self::meta( $post->ID, self::META_DATA ) );

		if ( $values ) {
			$record['values'] = is_array( $data ) ? $data : array();
		}

		$record['field_count'] = is_array( $data ) ? count( $data ) : 0;

		return $record;
	}

	/**
	 * One raw meta value, or ''.
	 *
	 * @param int    $post_id Post id.
	 * @param string $key     Meta key.
	 * @return string
	 */
	public static function meta( $post_id, $key ) {
		$row = Form_DB::read_one( (int) $post_id, (string) $key );

		return 'one' === $row['status'] ? (string) $row['value'] : '';
	}

	/**
	 * A notification record and the row it lives in.
	 *
	 * @param int    $post_id Post id.
	 * @param string $kind    `admin` or `confirmation`.
	 * @return array{record:?array,raw:string,meta_id:int}
	 */
	public static function notification_state( $post_id, $kind = 'admin' ) {
		$row = Form_DB::read_one( (int) $post_id, self::notification_key( $kind ) );

		return array(
			'record'  => 'one' === $row['status'] ? self::decode( (string) $row['value'] ) : null,
			'raw'     => 'one' === $row['status'] ? (string) $row['value'] : '',
			'meta_id' => 'one' === $row['status'] ? (int) $row['meta_id'] : 0,
		);
	}

	/**
	 * Compare-and-swap a notification record.
	 *
	 * @param int    $post_id  Post id.
	 * @param string $kind     `admin` or `confirmation`.
	 * @param array  $record   The new record.
	 * @param array  $expected The state read by `notification_state()`.
	 * @return bool
	 */
	public static function cas_notification( $post_id, $kind, array $record, array $expected ) {
		$meta_id = isset( $expected['meta_id'] ) ? (int) $expected['meta_id'] : 0;
		$raw     = isset( $expected['raw'] ) ? (string) $expected['raw'] : '';

		if ( $meta_id < 1 ) {
			return false;
		}

		return Form_DB::cas_update(
			$meta_id,
			(string) wp_json_encode( $record ),
			$raw,
			(int) $post_id
		);
	}

	/**
	 * Rewrite a notification record without a guard.
	 *
	 * Used only where the caller already owns the record exclusively (the first
	 * write of a fresh submission) — every worker uses `cas_notification()`.
	 *
	 * @param int    $post_id Post id.
	 * @param string $kind    Kind.
	 * @param array  $record  Record.
	 * @return bool
	 */
	public static function write_notification( $post_id, $kind, array $record ) {
		$state = self::notification_state( $post_id, $kind );

		if ( $state['meta_id'] > 0 ) {
			return self::cas_notification( $post_id, $kind, $record, $state );
		}

		return self::write_meta( (int) $post_id, self::notification_key( $kind ), (string) wp_json_encode( $record ) );
	}

	/**
	 * Write one meta row directly.
	 *
	 * @param int    $post_id Post id.
	 * @param string $key     Meta key.
	 * @param string $value   Value.
	 * @return bool
	 */
	public static function write_meta( $post_id, $key, $value ) {
		global $wpdb;

		if ( ! isset( $wpdb ) || ! is_object( $wpdb ) ) {
			return false;
		}

		$inserted = $wpdb->insert(
			$wpdb->postmeta,
			array(
				'post_id'    => (int) $post_id,
				'meta_key'   => (string) $key, // phpcs:ignore WordPress.DB.SlowDBQuery.slow_db_query_meta_key
				'meta_value' => (string) $value, // phpcs:ignore WordPress.DB.SlowDBQuery.slow_db_query_meta_value
			),
			array( '%d', '%s', '%s' )
		);

		if ( false !== $inserted && function_exists( 'wp_cache_delete' ) ) {
			wp_cache_delete( (int) $post_id, 'post_meta' );
		}

		return false !== $inserted;
	}

	/**
	 * Submissions of one form, metadata only by default.
	 *
	 * @param string $form_id The form's internal identifier.
	 * @param array  $args {
	 *     @type string $status       A post status, or `any` (default `publish`).
	 *     @type int    $limit        Maximum rows.
	 *     @type int    $offset       Offset.
	 *     @type bool   $with_values  Whether to include values (default false).
	 * }
	 * @return array<int,array>
	 */
	public static function list_for_form( $form_id, array $args = array() ) {
		$status      = isset( $args['status'] ) ? (string) $args['status'] : 'publish';
		$limit       = isset( $args['limit'] ) ? (int) $args['limit'] : 100;
		$offset      = isset( $args['offset'] ) ? (int) $args['offset'] : 0;
		$with_values = ! empty( $args['with_values'] );
		$statuses    = 'any' === $status ? array( 'publish', 'draft', 'pending', 'private', 'trash' ) : array( $status );

		$per_page = $limit < 0 ? -1 : max( 1, $limit );

		$posts = get_posts(
			array(
				'post_type'        => Form_Post_Types::ENTRY,
				'post_status'      => $statuses,
				'posts_per_page'   => $per_page,
				'offset'           => max( 0, $offset ),
				'orderby'          => 'date',
				'order'            => 'DESC',
				'suppress_filters' => false,
				'meta_query'       => array( // phpcs:ignore WordPress.DB.SlowDBQuery.slow_db_query_meta_query
					array(
						'key'   => self::META_FORM_ID,
						'value' => (string) $form_id,
					),
				),
			)
		);

		$out = array();

		foreach ( (array) $posts as $post ) {
			$record = self::get( (int) $post->ID, $with_values );

			if ( ! is_wp_error( $record ) ) {
				$out[] = $record;
			}
		}

		return $out;
	}

	/**
	 * How many submissions a form holds, in one status.
	 *
	 * @param string $form_id The form's internal identifier.
	 * @param string $status  Status, or `any`.
	 * @return int
	 */
	public static function count_for_form( $form_id, $status = 'publish' ) {
		$statuses = 'any' === $status ? array( 'publish', 'draft', 'pending', 'private', 'trash' ) : array( $status );

		$query = new \WP_Query(
			array(
				'post_type'      => Form_Post_Types::ENTRY,
				'post_status'    => $statuses,
				'posts_per_page' => 1,
				'fields'         => 'ids',
				'no_found_rows'  => false,
				'meta_query'     => array( // phpcs:ignore WordPress.DB.SlowDBQuery.slow_db_query_meta_query
					array(
						'key'   => self::META_FORM_ID,
						'value' => (string) $form_id,
					),
				),
			)
		);

		return (int) $query->found_posts;
	}

	/**
	 * Move a submission to the trash.
	 *
	 * @param int $post_id The entry.
	 * @param int $actor   The acting user, for the audit row.
	 * @return bool|\WP_Error
	 */
	public static function trash( $post_id, $actor = 0 ) {
		$record = self::get( (int) $post_id, false );

		if ( is_wp_error( $record ) ) {
			return $record;
		}

		if ( 'trash' === $record['status'] ) {
			return true;
		}

		$done = wp_trash_post( (int) $post_id );

		if ( ! $done ) {
			return new \WP_Error( 'form_submission_trash_failed', __( 'The submission could not be moved to the trash.', 'agentshell-forms' ) );
		}

		Form_Audit::record(
			'form_submission_trashed',
			array(
				'submission' => (int) $post_id,
				'form_id'    => (string) $record['form_id'],
			),
			(int) $actor
		);

		return true;
	}

	/**
	 * Restore a submission from the trash.
	 *
	 * @param int $post_id The entry.
	 * @param int $actor   The acting user.
	 * @return bool|\WP_Error
	 */
	public static function restore( $post_id, $actor = 0 ) {
		$record = self::get( (int) $post_id, false );

		if ( is_wp_error( $record ) ) {
			return $record;
		}

		if ( 'trash' !== $record['status'] ) {
			return true;
		}

		$done = wp_untrash_post( (int) $post_id );

		if ( ! $done ) {
			return new \WP_Error( 'form_submission_restore_failed', __( 'The submission could not be restored.', 'agentshell-forms' ) );
		}

		Form_Audit::record(
			'form_submission_restored',
			array(
				'submission' => (int) $post_id,
				'form_id'    => (string) $record['form_id'],
			),
			(int) $actor
		);

		return true;
	}

	/**
	 * Hard-delete a submission.
	 *
	 * The per-post `delete_post` capability is re-checked at the moment of
	 * deletion for a real actor (§6.5). A system actor (retention, privacy
	 * eraser, cron) passes 0 and is not subject to a user check — it has no
	 * user to check.
	 *
	 * @param int  $post_id The entry.
	 * @param int  $actor   The acting user, or 0 for a system operation.
	 * @param bool $force   Must be true: this operation is irreversible.
	 * @return bool|\WP_Error
	 */
	public static function delete_permanently( $post_id, $actor = 0, $force = false ) {
		$post_id = (int) $post_id;

		$record = self::get( $post_id, false );

		if ( is_wp_error( $record ) ) {
			// A record that is already gone is a deletion that succeeded, not
			// one that failed: retention and erasure are retried, and a retry
			// must not report a failure for work that is already done.
			if ( 'form_submission_not_found' === $record->get_error_code() ) {
				return true;
			}

			return $record;
		}

		if ( ! $force ) {
			return new \WP_Error(
				'form_submission_delete_unconfirmed',
				__( 'A permanent deletion requires an explicit confirmation.', 'agentshell-forms' )
			);
		}

		if ( $actor > 0 && ! user_can( (int) $actor, 'delete_post', $post_id ) ) {
			return new \WP_Error(
				'form_submission_delete_forbidden',
				__( 'You are not allowed to delete this submission.', 'agentshell-forms' )
			);
		}

		$deleted = wp_delete_post( $post_id, true );

		if ( ! $deleted ) {
			return new \WP_Error( 'form_submission_delete_failed', __( 'The submission could not be deleted.', 'agentshell-forms' ) );
		}

		Form_Audit::record(
			'form_submission_deleted',
			array(
				'submission' => $post_id,
				'form_id'    => (string) $record['form_id'],
				'system'     => 0 === (int) $actor,
			),
			(int) $actor
		);

		return true;
	}

	/**
	 * Delete every submission of a form. The erasure path used by the privacy
	 * eraser and by an explicit "delete this form's submissions" action.
	 *
	 * @param string $form_id Form id.
	 * @param int    $actor   Actor, or 0.
	 * @return array{deleted:int,failed:int}
	 */
	public static function delete_all_for_form( $form_id, $actor = 0 ) {
		$deleted = 0;
		$failed  = 0;

		foreach ( self::list_for_form( $form_id, array( 'status' => 'any', 'limit' => -1 ) ) as $record ) {
			$result = self::delete_permanently( (int) $record['id'], $actor, true );

			if ( is_wp_error( $result ) ) {
				$failed++;
			} else {
				$deleted++;
			}
		}

		return array( 'deleted' => $deleted, 'failed' => $failed );
	}

	/**
	 * Every submission whose stored values contain an email address.
	 *
	 * The match is an exact, case-insensitive comparison against every scalar
	 * value in the record, because a submission was validated against the
	 * definition that was published *then* and the current definition may name
	 * different fields. Scanning values answers the subject-access question
	 * ("what do you hold about this address") without pretending to know which
	 * key held it.
	 *
	 * @param string $email Email address.
	 * @param int    $limit Maximum records to return.
	 * @return array<int,array>
	 */
	public static function find_by_email( $email, $limit = 500 ) {
		$email = strtolower( trim( (string) $email ) );

		if ( '' === $email ) {
			return array();
		}

		$posts = get_posts(
			array(
				'post_type'      => Form_Post_Types::ENTRY,
				'post_status'    => array( 'publish', 'draft', 'pending', 'private', 'trash' ),
				'posts_per_page' => max( 1, (int) $limit ),
				'orderby'        => 'date',
				'order'          => 'DESC',
			)
		);

		$found = array();

		foreach ( (array) $posts as $post ) {
			$record = self::get( (int) $post->ID, true );

			if ( is_wp_error( $record ) || ! is_array( $record['values'] ) ) {
				continue;
			}

			if ( self::values_contain( $record['values'], $email ) ) {
				$found[] = $record;
			}
		}

		return $found;
	}

	/**
	 * Does a value tree contain an exact email?
	 *
	 * @param mixed  $value The value.
	 * @param string $email Lower-cased email.
	 * @return bool
	 */
	private static function values_contain( $value, $email ) {
		if ( is_array( $value ) ) {
			foreach ( $value as $item ) {
				if ( self::values_contain( $item, $email ) ) {
					return true;
				}
			}

			return false;
		}

		if ( is_bool( $value ) || null === $value ) {
			return false;
		}

		return strtolower( trim( (string) $value ) ) === $email;
	}

	/**
	 * The rows an export needs, one per submission, plus the header.
	 *
	 * @param string $form_id    The form's internal identifier.
	 * @param array  $definition The published definition (for labels and keys).
	 * @param string $status     Status to export.
	 * @return array{columns:array<int,string>,keys:array<int,string>,rows:array<int,array<int,string>>}
	 */
	public static function export_table( $form_id, array $definition, $status = 'publish' ) {
		$columns = array(
			__( 'ID', 'agentshell-forms' ),
			__( 'Received (UTC)', 'agentshell-forms' ),
			__( 'Form version', 'agentshell-forms' ),
			__( 'Spam status', 'agentshell-forms' ),
			__( 'Notification', 'agentshell-forms' ),
		);

		$keys = array();
		$headers = array();

		foreach ( (array) ( $definition['fields'] ?? array() ) as $field ) {
			if ( ! is_array( $field ) || ! isset( $field['key'] ) ) {
				continue;
			}

			$key   = (string) $field['key'];
			$label = isset( $field['label'] ) && '' !== (string) $field['label'] ? (string) $field['label'] : $key;

			$keys[]    = $key;
			$headers[] = $label;
		}

		$rows = array();

		foreach ( self::list_for_form( $form_id, array( 'status' => $status, 'limit' => -1, 'with_values' => true ) ) as $record ) {
			$row = array(
				(string) $record['id'],
				(string) $record['received_at'],
				(string) $record['form_version'],
				(string) $record['spam_status'],
				(string) ( is_array( $record['notification'] ) && isset( $record['notification']['status'] ) ? $record['notification']['status'] : '' ),
			);

			foreach ( $keys as $key ) {
				$value = isset( $record['values'][ $key ] ) ? $record['values'][ $key ] : '';

				if ( is_array( $value ) ) {
					$value = implode( '; ', array_map( 'strval', $value ) );
				} elseif ( is_bool( $value ) ) {
					$value = $value ? __( 'Yes', 'agentshell-forms' ) : __( 'No', 'agentshell-forms' );
				}

				$row[] = (string) $value;
			}

			$rows[] = $row;
		}

		return array(
			'form_id' => (string) $form_id,
			'columns' => array_merge( $columns, $headers ),
			'keys'    => $keys,
			'rows'    => $rows,
		);
	}

	/**
	 * Render an export table as CSV.
	 *
	 * ## Spreadsheet formula injection
	 *
	 * A cell beginning with `=`, `+`, `-`, `@`, a tab or a carriage return is
	 * executed as a formula by Excel and by several other spreadsheets. A
	 * visitor controls field values, so a message beginning `=HYPERLINK(...)`
	 * is an attempt to run something in the operator's spreadsheet. Every such
	 * cell is prefixed with a single quote, which every major spreadsheet
	 * treats as "this is text" and does not display.
	 *
	 * The prefix is applied **after** the value is known to be a string and
	 * **before** quoting, and every cell is quoted with `"` doubled inside,
	 * so a value containing a comma, a quote or a newline stays in its own
	 * cell.
	 *
	 * @param array $table The table from `export_table()`.
	 * @return string
	 */
	public static function to_csv( array $table ) {
		$lines = array();
		$lines[] = self::csv_line( (array) $table['columns'] );

		foreach ( (array) $table['rows'] as $row ) {
			$lines[] = self::csv_line( (array) $row );
		}

		return implode( "\r\n", $lines ) . "\r\n";
	}

	/**
	 * One CSV line.
	 *
	 * @param array $cells Cells.
	 * @return string
	 */
	private static function csv_line( array $cells ) {
		$out = array();

		foreach ( $cells as $cell ) {
			$out[] = self::csv_cell( (string) $cell );
		}

		return implode( ',', $out );
	}

	/**
	 * One CSV cell: formula-injection prefix, then RFC 4180 quoting.
	 *
	 * @param string $value Value.
	 * @return string
	 */
	public static function csv_cell( $value ) {
		$value = (string) $value;

		if ( '' !== $value && false !== strpos( "=+-@\t\r", $value[0] ) ) {
			$value = "'" . $value;
		}

		return '"' . str_replace( '"', '""', $value ) . '"';
	}

	/**
	 * Render an export table as JSON.
	 *
	 * JSON is not executable, so it needs no formula prefix; it is encoded with
	 * `wp_json_encode()` and the caller sends it as `application/json`.
	 *
	 * @param array $table The table from `export_table()`.
	 * @return string
	 */
	public static function to_json( array $table ) {
		$records = array();

		foreach ( (array) $table['rows'] as $row ) {
			$record = array();

			foreach ( (array) $table['columns'] as $index => $column ) {
				$record[ (string) $column ] = isset( $row[ $index ] ) ? (string) $row[ $index ] : '';
			}

			$records[] = $record;
		}

		return (string) wp_json_encode(
			array(
				'form_id'   => isset( $table['form_id'] ) ? (string) $table['form_id'] : '',
				'columns'   => array_values( (array) $table['columns'] ),
				'records'   => $records,
				'count'     => count( $records ),
				'exported_at' => gmdate( 'c' ),
			)
		);
	}

	/**
	 * Hard-delete submissions past their form's retention period.
	 *
	 * The period is the form's `settings.storage.retain_days`, or the site
	 * default when the form says 0. A form whose definition cannot be read
	 * falls back to the site default rather than being skipped: a broken form
	 * is not a reason to keep personal data forever.
	 *
	 * The purge is idempotent — a deletion that fails leaves the row for the
	 * next run — and it writes one audit row per form with the count and the
	 * period, so the operator can see what happened.
	 *
	 * @param int|null $now Timestamp, for tests.
	 * @return array{forms:int,deleted:int,failed:int,details:array<int,array>}
	 */
	public static function purge_expired( $now = null ) {
		$now      = null === $now ? time() : (int) $now;
		$default  = self::site_retention_days();
		$details  = array();
		$deleted  = 0;
		$failed   = 0;
		$forms    = 0;

		$known = array();

		$form_posts = get_posts(
			array(
				'post_type'      => Form_Post_Types::FORM,
				'post_status'    => array( 'publish', 'draft', 'pending', 'private', 'trash' ),
				'posts_per_page' => -1,
				'orderby'        => 'ID',
				'order'          => 'ASC',
			)
		);

		foreach ( (array) $form_posts as $form_post ) {
			$state = Form_Definition::get_by_post_id( (int) $form_post->ID );

			if ( is_wp_error( $state ) ) {
				continue;
			}

			$form_id = (string) $state['form_id'];
			$known[] = $form_id;
			$definition = is_array( $state['published'] ) ? $state['published'] : $state['working'];

			$days = $default;

			if ( is_array( $definition ) && isset( $definition['settings']['storage']['retain_days'] ) ) {
				$declared = (int) $definition['settings']['storage']['retain_days'];
				if ( $declared > 0 ) {
					$days = $declared;
				}
			}

			$forms++;
			$cutoff = $now - ( $days * DAY_IN_SECONDS );

			$posts = get_posts(
				array(
					'post_type'      => Form_Post_Types::ENTRY,
					'post_status'    => array( 'publish', 'draft', 'pending', 'private', 'trash' ),
					'posts_per_page' => -1,
					'fields'         => 'ids',
					'orderby'        => 'ID',
					'order'          => 'ASC',
					'date_query'     => array(
						array(
							'column'    => 'post_date_gmt',
							'before'    => gmdate( 'Y-m-d H:i:s', $cutoff ),
							'inclusive' => true,
						),
					),
					'meta_query'     => array( // phpcs:ignore WordPress.DB.SlowDBQuery.slow_db_query_meta_query
						array(
							'key'   => self::META_FORM_ID,
							'value' => $form_id,
						),
					),
				)
			);

			$form_deleted = 0;
			$form_failed  = 0;

			foreach ( (array) $posts as $entry_id ) {
				$result = self::delete_permanently( (int) $entry_id, 0, true );

				if ( is_wp_error( $result ) ) {
					$form_failed++;
				} else {
					$form_deleted++;
				}
			}

			$deleted += $form_deleted;
			$failed  += $form_failed;

			if ( $form_deleted > 0 || $form_failed > 0 ) {
				$details[] = array(
					'form_id' => $form_id,
					'days'    => $days,
					'deleted' => $form_deleted,
					'failed'  => $form_failed,
				);

				Form_Audit::record(
					'form_submissions_purged',
					array(
						'form_id' => $form_id,
						'days'    => (int) $days,
						'deleted' => (int) $form_deleted,
						'failed'  => (int) $form_failed,
					),
					0
				);
			}
		}

		// Entries whose form no longer exists. Nothing will ever read them, so
		// nothing will ever apply a per-form period to them — which makes them
		// the one way a submission could outlive every retention promise the
		// site makes. The site default is the only period that can apply, and
		// the pass is audited by form id so the operator can see what went.
		$orphans = self::purge_orphans( $now, $default, $known );

		return array(
			'forms'   => $forms,
			'deleted' => $deleted + $orphans['deleted'],
			'failed'  => $failed + $orphans['failed'],
			'details' => array_merge( $details, $orphans['details'] ),
		);
	}

	/**
	 * Hard-delete submissions whose form is gone.
	 *
	 * @param int   $now     Reference time.
	 * @param int   $default The site retention period, in days.
	 * @param array $known   The form ids that still exist.
	 * @return array{deleted:int,failed:int,details:array<int,array>}
	 */
	private static function purge_orphans( $now, $default, array $known ) {
		$cutoff = (int) $now - ( (int) $default * DAY_IN_SECONDS );

		$args = array(
			'post_type'      => Form_Post_Types::ENTRY,
			'post_status'    => array( 'publish', 'draft', 'pending', 'private', 'trash' ),
			'posts_per_page' => -1,
			'fields'         => 'ids',
			'orderby'        => 'ID',
			'order'          => 'ASC',
			'date_query'     => array(
				array(
					'column'    => 'post_date_gmt',
					'before'    => gmdate( 'Y-m-d H:i:s', $cutoff ),
					'inclusive' => true,
				),
			),
		);

		if ( ! empty( $known ) ) {
			$args['meta_query'] = array( // phpcs:ignore WordPress.DB.SlowDBQuery.slow_db_query_meta_query
				array(
					'key'     => self::META_FORM_ID,
					'value'   => array_values( $known ),
					'compare' => 'NOT IN',
				),
			);
		}

		$ids = get_posts( $args );

		$deleted = 0;
		$failed  = 0;
		$by_form = array();

		foreach ( (array) $ids as $entry_id ) {
			$form_id = (string) self::meta( (int) $entry_id, self::META_FORM_ID );

			if ( ! isset( $by_form[ $form_id ] ) ) {
				$by_form[ $form_id ] = array( 'deleted' => 0, 'failed' => 0 );
			}

			$result = self::delete_permanently( (int) $entry_id, 0, true );

			if ( is_wp_error( $result ) ) {
				$by_form[ $form_id ]['failed']++;
				$failed++;
				continue;
			}

			$by_form[ $form_id ]['deleted']++;
			$deleted++;
		}

		$details = array();

		foreach ( $by_form as $form_id => $counts ) {
			if ( 0 === $counts['deleted'] && 0 === $counts['failed'] ) {
				continue;
			}

			$details[] = array(
				'form_id' => (string) $form_id,
				'days'    => (int) $default,
				'deleted' => (int) $counts['deleted'],
				'failed'  => (int) $counts['failed'],
				'reason'  => 'unknown_form',
			);

			Form_Audit::record(
				'form_submissions_purged',
				array(
					'form_id' => (string) $form_id,
					'days'    => (int) $default,
					'deleted' => (int) $counts['deleted'],
					'failed'  => (int) $counts['failed'],
					'reason'  => 'unknown_form',
				),
				0
			);
		}

		return array(
			'deleted' => $deleted,
			'failed'  => $failed,
			'details' => $details,
		);
	}

	/**
	 * Decode a JSON meta value.
	 *
	 * @param string $raw Raw value.
	 * @return array|null
	 */
	private static function decode( $raw ) {
		if ( ! is_string( $raw ) || '' === $raw ) {
			return null;
		}

		$decoded = json_decode( $raw, true );

		return is_array( $decoded ) ? $decoded : null;
	}
}
